import java.util.*;

public class Main {
    List<String> fullJustify(String[] words, int maxWidth) {
        List<String> lines = new ArrayList<>();
        int i = 0, n = words.length;
        while (i < n) {
            List<String> lineWords = new ArrayList<>();
            int length = 0;
            while (i < n && length + lineWords.size() + words[i].length() <= maxWidth) {
                lineWords.add(words[i]);
                length += words[i].length();
                i++;
            }
            StringBuilder line = new StringBuilder();
            if (i == n || lineWords.size() == 1) {
                line.append(String.join(" ", lineWords));
                while (line.length() < maxWidth) line.append(' ');
            } else {
                int gaps = lineWords.size() - 1;
                int[] gapSpaces = new int[gaps];
                Arrays.fill(gapSpaces, 1);                                  // start with the single mandatory space
                int remaining = maxWidth - length - gaps;
                int gapIndex = 0;
                while (remaining > 0) {                                       // add one more space, cycling through gaps
                    gapSpaces[gapIndex]++;
                    remaining--;
                    gapIndex = (gapIndex + 1) % gaps;
                }
                line.append(lineWords.get(0));
                for (int idx = 0; idx < gaps; idx++) {
                    for (int s = 0; s < gapSpaces[idx]; s++) line.append(' ');
                    line.append(lineWords.get(idx + 1));
                }
            }
            lines.add(line.toString());
        }
        return lines;
    }

    public static void main(String[] args) {
        String[] words = {"This", "is", "an", "example", "of", "text", "justification."};
        int maxWidth = 16;
        Main solution = new Main();
        for (String line : solution.fullJustify(words, maxWidth)) {
            System.out.println("\"" + line + "\"");
        }
    }
}

